public class StackMemoryDemo {
    public static int addFive(int x) {
        // Frame 3 pushed: x = 10, local result
        int result = x + 5;
        return result; // Frame 3 popped! Memory reclaimed.
    }

    public static int compute(int a) {
        // Frame 2 pushed: a = 10, local val
        int val = addFive(a); 
        return val * 2; // Frame 2 popped!
    }

    public static void main(String[] args) {
        // Frame 1 pushed: main() starts
        int num = 10;
        int output = compute(num);
        System.out.println("Final Output: " + output);
        // Frame 1 popped! Program finishes.
    }
}

