practiceProblems.solutionCode:
public class Main {
    public static double addTax(double amount) {
        return amount * 1.10;
    }

    public static double calculateTripCost(int days, double hotelRatePerDay, double flightCost) {
        double hotelTotal = days * hotelRatePerDay;
        double taxedHotel = addTax(hotelTotal);
        return taxedHotel + flightCost;
    }

    public static void main(String[] args) {
        double cost = calculateTripCost(3, 100.0, 250.0);
        System.out.println("Trip Cost: $" + cost);
    }
}

