practiceProblems.solutionCode:
public class Main {
    public static void traceDepth(int n) {
        System.out.println("Enter depth " + n);
        if (n > 1) {
            traceDepth(n - 1);
        }
        System.out.println("Exit depth " + n);
    }

    public static void main(String[] args) {
        traceDepth(3);
    }
}

