public class Main {
    public static int first(int x) {
        return x + 2;
    }

    public static int second(int y) {
        return first(y) * 3;
    }

    public static int third(int z) {
        return second(z) - 5;
    }

    public static void main(String[] args) {
        int res = third(4);
        System.out.println("Result: " + res);
    }
}
